// Rng: the SplitMix64 generator every module uses.
// Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
package common;

public final class Rng {
    private long state;

    public Rng(long seed) {
        state = seed;
    }

    public long next() {
        state += 0x9E3779B97F4A7C15L;
        long z = state;
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }
}
